	["Accent"] = "Akzent",
	["Accent background"] = "Akzenthintergrund",
	["Accent bar"] = "Akzentleiste",
	["Accent border on the member you have targeted."] = "Akzentrand am Mitglied, das Ihr anvisiert habt.",
	["Accent borders and headers with an accent gradient behind the model."] = "Akzentränder und -überschriften mit einem Akzentverlauf hinter dem Modell.",
	["Accent color in combat"] = "Akzentfarbe im Kampf",
