	["Bar %d (hidden)"] = "Leiste %d (ausgeblendet)",
	["Bar %d (off)"] = "Leiste %d (aus)",
	["Bar 1"] = "Leiste 1",
	["Bar 1 shows the actions of vehicles, override bars and possessed units, like Blizzard's main bar, and stays shown in vehicles. Always on while EldoUI hides Blizzard's override bar."] = "Leiste 1 zeigt die Aktionen von Fahrzeugen, Ersatzleisten und übernommenen Einheiten, wie Blizzards Hauptleiste, und bleibt in Fahrzeugen sichtbar. Immer an, solange EldoUI Blizzards Ersatzleiste ausblendet.",
	["Bar 1 shows vehicle actions"] = "Leiste 1 zeigt Fahrzeugaktionen",
	["Bar 1 switches page with stance, form and stealth, like Blizzard's main bar."] = "Leiste 1 wechselt die Seite mit Haltung, Gestalt und Verstohlenheit, wie Blizzards Hauptleiste.",
	["Bar 1: Blizzard's override and vehicle bar is hidden and EldoUI's bar 1 shows the vehicle's actions (needs the Hide switch of Vehicle bars and bar 1 on). Blizzard's: its own skinned vehicle bar shows."] = "Leiste 1: Blizzards Ersatz- und Fahrzeugleiste wird ausgeblendet, und Leiste 1 von EldoUI zeigt die Aktionen des Fahrzeugs (benötigt den Schalter „Ausblenden“ der Fahrzeugleisten und Leiste 1 an). Blizzards: Ihre eigene Fahrzeugleiste erscheint mit Skin.",
	["Bar and log"] = "Leiste und Protokoll",
