	["Big"] = "Groß",
	["Big 38 px icons, easy to hit."] = "Große 38-px-Symbole, leicht zu treffen.",
	["Big 40 px buffs and 52 px debuffs, your own buffs first, colored time that blinks in the last 5 seconds."] = "Große 40-px-Stärkungszauber und 52-px-Schwächungszauber, Eure eigenen Stärkungszauber zuerst, farbige Zeit, die in den letzten 5 Sekunden blinkt.",
	["Big 48 px icons with the time under them; missing auras show faded."] = "Große 48-px-Symbole mit der Zeit darunter; fehlende Auren werden verblasst angezeigt.",
	["Big 56 px essential icons for a cooldown-centered HUD."] = "Große essenzielle 56-px-Symbole für ein HUD mit den Abklingzeiten im Mittelpunkt.",
	["Big arcing numbers on both sides of your character, the classic scrolling look."] = "Große Zahlen im Bogen auf beiden Seiten Eures Charakters, die klassische Optik des Kampftexts.",
	["Big buttons with their names."] = "Große Schaltflächen mit ihren Namen.",
	["Big defensive"] = "Großer Verteidigungszauber",
	["Big icon"] = "Großes Symbol",
	["Big icons shown at once. More than one makes the timeline longer, away from the bar, and may reach the frames next to it."] = "Gleichzeitig angezeigte große Symbole. Mehr als eines macht die Zeitleiste länger, weg von der Leiste, und kann die Rahmen daneben erreichen.",
	["Big item levels, red tint on worn gear, missing-enchant marks."] = "Große Gegenstandsstufen, rote Tönung bei beschädigter Ausrüstung, Markierungen für fehlende Verzauberungen.",
	["Big markers and a thick line, easy to read on a big screen."] = "Große Markierungen und eine dicke Linie, gut lesbar auf einem großen Bildschirm.",
	["Big rows and roll bars for high resolutions."] = "Große Zeilen und Wurfleisten für hohe Auflösungen.",
	["Big rows and text that read well from a distance."] = "Große Zeilen und Text, die sich aus der Entfernung gut lesen lassen.",
	["Big text"] = "Großer Text",
	["Big text and clock, whispers and chat hidden."] = "Großer Text und Uhr, Flüstern und Chat ausgeblendet.",
	["Big text in a wide panel, easy to read from a distance."] = "Großer Text in einem breiten Panel, aus der Entfernung gut lesbar.",
	["Big tiles in rows of five, sorted by role, health growing upward, power only on healers, your heals over time and every heal and shield on the way."] = "Große Kacheln in Fünferreihen, nach Rolle sortiert, Gesundheit wächst nach oben, Ressource nur bei Heilern, Eure Heilungen über Zeit sowie jede eingehende Heilung und jeder Schild.",
	["BigWigs"] = "BigWigs",
	["BigWigs %s"] = "BigWigs %s",
	["BigWigs already uses %s."] = "BigWigs verwendet bereits %s.",
	["BigWigs anchors left unchanged."] = "BigWigs-Anker unverändert gelassen.",
	["BigWigs bars now follow the EldoUI movers. Move them with /eui move."] = "Die Leisten von BigWigs folgen jetzt den Verschiebefeldern von EldoUI. Verschiebt sie mit /eui move.",
	["BigWigs has no profile called %s any more."] = "BigWigs hat kein Profil namens %s mehr.",
	["BigWigs integration"] = "BigWigs-Integration",
	["BigWigs is back on %s."] = "BigWigs ist wieder auf %s.",
	["BigWigs is not loaded, or this integration is off."] = "BigWigs ist nicht geladen, oder diese Integration ist aus.",
	["BigWigs messages mover"] = "Verschiebefeld für BigWigs-Nachrichten",
	["BigWigs only"] = "Nur BigWigs",
	["BigWigs refused the anchors: %s"] = "BigWigs hat die Anker abgelehnt: %s",
	["BigWigs' bars get EldoUI's thin border, texture and font, with the accent on bars about to end. Bar colors and sounds stay as set in BigWigs."] = "Die Leisten von BigWigs erhalten den dünnen Rand, die Textur und die Schrift von EldoUI, mit dem Akzent auf bald endenden Leisten. Leistenfarben und Sounds bleiben wie in BigWigs eingestellt.",
	["BigWigs: hide its normal bars in BigWigs' own Bars options if you want only the timeline."] = "BigWigs: Blendet seine normalen Leisten in den eigenen Leistenoptionen von BigWigs aus, wenn Ihr nur die Zeitleiste wollt.",
	["Bigger 30 px icons and 14 pt text in a column."] = "Größere 30-px-Symbole und 14-pt-Text in einer Spalte.",
	["Bigger red markers with the boss's number in kill order."] = "Größere rote Markierungen mit der Nummer des Bosses in der Kill-Reihenfolge.",
	["Bigger text and bars for big screens or sitting far away."] = "Größerer Text und größere Leisten für große Bildschirme oder großen Sitzabstand.",
	["Bigger text and roomier boxes, easy to read from afar."] = "Größerer Text und geräumigere Kästen, aus der Ferne gut lesbar.",
	["Bigger text for big screens or sitting back."] = "Größerer Text für große Bildschirme oder großen Sitzabstand.",
	["Bind keys"] = "Tasten belegen",
	["Bind spells and macros to clicks on party, raid and unit frames, and see every binding in the frame's tooltip."] = "Belegt Klicks auf Gruppen-, Schlachtzugs- und Einheitenrahmen mit Zaubern und Makros und zeigt jede Belegung im Tooltip des Rahmens.",
	["Bind spells and macros to clicks, modifier clicks, keys or the mouse wheel on party, raid and unit frames. Saved per class."] = "Belegt Klicks, Modifikatorklicks, Tasten oder das Mausrad auf Gruppen-, Schlachtzugs- und Einheitenrahmen mit Zaubern und Makros. Pro Klasse gespeichert.",
	["Bind tag"] = "Bindungsangabe",
	["Bindings"] = "Belegungen",
