	["Color ranges"] = "Farbbereiche",
	["Color ranges and tick marks go on the power bar. Turn the power bar on (Bars tab) to use them."] = "Farbbereiche und Teilstriche liegen auf der Ressourcenleiste. Schaltet die Ressourcenleiste ein (Reiter Leisten), um sie zu nutzen.",
	["Color the bars by magic, curse, disease, poison or bleed (the game picks the color), or use the accent color."] = "Färbt die Leisten nach Magie, Fluch, Krankheit, Gift oder Blutung (das Spiel wählt die Farbe) oder nutzt die Akzentfarbe.",
	["Color the icon while you can't cast it, like action buttons without enough mana."] = "Färbt das Symbol, solange Ihr den Zauber nicht wirken könnt, wie Aktionstasten ohne genug Mana.",
	["Color the pet bar border by the happiness the game reports for your pet (green, yellow, red)."] = "Färbt den Rand der Begleiterleiste nach der Zufriedenheit, die das Spiel für Euer Tier meldet (grün, gelb, rot).",
