	["Descending turns the order around (last group or Z first)."] = "Absteigend dreht die Reihenfolge um (letzte Gruppe oder Z zuerst).",
	["Destroy %s"] = "%s zerstören",
	["Details uses the profile you had before EldoUI's import again. The EldoUI profiles stay in Details' list."] = "Details verwendet wieder das Profil, das Ihr vor dem Import durch EldoUI hattet. Die EldoUI-Profile bleiben in der Liste von Details.",
	["Details!"] = "Details!",
	["Details! Window 1"] = "Details!-Fenster 1",
	["Details! Window 2"] = "Details!-Fenster 2",
	["Details! integration"] = "Details!-Integration",
	["Details' meter window goes to the layout's meter spot, and move mode places it like any EldoUI frame. Unchecked, Details keeps its own spot."] = "Das Messfenster von Details wandert an den Messplatz des Layouts, und der Verschiebemodus platziert es wie jeden EldoUI-Rahmen. Ohne Haken behält Details seinen eigenen Platz.",
	["Detect the same run"] = "Denselben Durchlauf erkennen",
