	["Dim the screen"] = "Bildschirm abdunkeln",
	["Direction icons are added in. From the center keeps every row centered."] = "Richtung, in die Symbole hinzukommen. Von der Mitte hält jede Reihe zentriert.",
	["Direction new bars are added in."] = "Richtung, in die neue Leisten hinzukommen.",
	["Direction new buffs are added in a row."] = "Richtung, in die neue Stärkungszauber in einer Reihe hinzukommen.",
	["Direction new debuffs are added in a row."] = "Richtung, in die neue Schwächungszauber in einer Reihe hinzukommen.",
