	["Down (newest at the top)"] = "Nach unten (neueste oben)",
	["Download / upload"] = "Download / Upload",
	["Drag a spell or macro onto the text box, or type a spell name. Macro text starts with /, for example /cast [@mouseover] Renew. Right-click the action button to go back. The game's own Click Casting wins on the same click."] = "Zieht einen Zauber oder ein Makro auf das Textfeld oder gebt einen Zaubernamen ein. Makrotext beginnt mit /, zum Beispiel /cast [@mouseover] Erneuerung. Rechtsklick auf die Aktionstaste führt zurück. Die eigenen Klickzauber des Spiels haben beim selben Klick Vorrang.",
	["Drag handles in move mode"] = "Ziehgriffe im Verschiebemodus",
	["Drag icons between groups, or onto empty screen as free icons."] = "Zieht Symbole zwischen Gruppen hin und her oder auf freien Bildschirm als freie Symbole.",
	["Drag the big text where you want it."] = "Zieht den großen Text dorthin, wo Ihr ihn haben wollt.",
	["Drag to change the area's width and height. The opposite corner stays put."] = "Ziehen, um Breite und Höhe des Bereichs zu ändern. Die gegenüberliegende Ecke bleibt, wo sie ist.",
	["Drag to move. Right-click resets it to the layout position."] = "Ziehen zum Verschieben. Rechtsklick setzt es auf die Position im Layout zurück.",
	["Dragging, the mouse wheel scale and the reset of the character window are on the Move windows page, with every other Blizzard window."] = "Ziehen, Skalieren mit dem Mausrad und das Zurücksetzen des Charakterfensters findet Ihr auf der Seite Fenster verschieben, mit allen anderen Blizzard-Fenstern.",
	["Drake"] = "Drache",
	["Draw"] = "Zeichnen",
	["Draw a background behind the panel. Off leaves only the text, which can be hard to read on a bright minimap."] = "Zeichnet einen Hintergrund hinter das Panel. Aus lässt nur den Text, der auf einer hellen Minikarte schwer lesbar sein kann.",
	["Draw a bright edge along the cooldown swipe."] = "Zeichnet eine helle Kante entlang der Abklingzeitanzeige.",
	["Draw an EldoUI panel behind the bar."] = "Zeichnet ein EldoUI-Panel hinter die Leiste.",
	["Draw one"] = "Eine ziehen",
	["Draw the bar's dark background and border. Off leaves only the text."] = "Zeichnet den dunklen Hintergrund und Rand der Leiste. Aus lässt nur den Text.",
	["Draw the packs and the picked route on the Loot Guide's dungeon map too. Its own boss markers stay."] = "Zeichnet die Gegnergruppen und die gewählte Route auch auf die Dungeonkarte des Loot Guide. Dessen eigene Bossmarkierungen bleiben.",
	["Draw the path of each patrolling pack as a thin line."] = "Zeichnet den Weg jeder patrouillierenden Gegnergruppe als dünne Linie.",
	["Draw the thin border around the panel."] = "Zeichnet den dünnen Rand um das Panel.",
	["Draw three"] = "Drei ziehen",
	["Drawn by"] = "Dargestellt von",
	["Draws an EldoUI panel (art style, border and colors from the General page) around the Details windows."] = "Zeichnet ein EldoUI-Panel (Grafikstil, Rand und Farben von der Seite Allgemein) um die Details-Fenster.",
	["Drink"] = "Trinken",
	["Drink, mana potion, health potion and healthstone, potions first."] = "Trinken, Manatrank, Heiltrank und Gesundheitsstein, Tränke zuerst.",
	["Drop Alliance banners against the Horde; four in a row wins."] = "Werft Allianzbanner gegen die Horde ein; vier in einer Reihe gewinnen.",
	["Drop an item on the section's title in the bag window."] = "Legt einen Gegenstand auf dem Titel des Abschnitts im Taschenfenster ab.",
	["Drop the EldoUI positions saved for Edit Mode layouts; the current positions stay."] = "Verwirft die für Layouts des Bearbeitungsmodus gespeicherten EldoUI-Positionen; die aktuellen Positionen bleiben.",
	["Druid mana"] = "Druidenmana",
	["Druid mana bar height."] = "Höhe der Druiden-Manaleiste.",
	["Druid mana in forms"] = "Druidenmana in Gestalten",
	["Druid or Primalist"] = "Druide oder Primalist",
	["Duel declined"] = "Duell abgelehnt",
	["Duel request"] = "Duellanfrage",
	["Duel requests from members of muted guilds are declined, and one chat line names who and which guild. Not in combat. This acts for you. Off by default."] = "Duellanfragen von Mitgliedern stummgeschalteter Gilden werden abgelehnt, und eine Chatzeile nennt, wer es war und welche Gilde. Nicht im Kampf. Dies handelt für Euch. Standardmäßig aus.",
	["Dungeon"] = "Dungeon",
	["Dungeon Routes"] = "Dungeonrouten",
	["Dungeon Routes: \"%s\" added to %s."] = "Dungeonrouten: \"%s\" zu %s hinzugefügt.",
	["Dungeon Routes: no dungeon called \"%s\"."] = "Dungeonrouten: kein Dungeon namens \"%s\".",
	["Dungeon Routes: the route was not added (%s)."] = "Dungeonrouten: Die Route wurde nicht hinzugefügt (%s).",
	["Dungeon Routes: there is no such route to export."] = "Dungeonrouten: Diese Route gibt es nicht, sie kann nicht exportiert werden.",
	["Dungeon boss"] = "Dungeonboss",
	["Dungeon data could not load"] = "Dungeondaten konnten nicht geladen werden",
	["Dungeon data is not installed"] = "Dungeondaten sind nicht installiert",
	["Dungeon data is switched off"] = "Dungeondaten sind ausgeschaltet",
	["Dungeon data is too old"] = "Dungeondaten sind zu alt",
	["Dungeon data loads out of combat"] = "Dungeondaten laden außerhalb des Kampfes",
	["Dungeon difficulty"] = "Dungeonschwierigkeit",
	["Dungeon entered"] = "Dungeon betreten",
	["Dungeon map on the world map"] = "Dungeonkarte auf der Weltkarte",
	["Dungeon route"] = "Dungeonroute",
	["Dungeon route: %s"] = "Dungeonroute: %s",
	["Dungeon routes"] = "Dungeonrouten",
	["Dungeon runs. These count toward the hourly limit."] = "Dungeondurchläufe. Diese zählen zum Stundenlimit.",
	["Dungeons window"] = "Dungeonfenster",
