	["English, large"] = "Englisch, groß",
	["Enlarges timers and keeps long timers hidden at the times that suit your role: tank 10 s and 60 s, healer 8 s and 90 s, damage 7 s and 45 s."] = "Vergrößert Timer und hält lange Timer zu den Zeiten verborgen, die zu Eurer Rolle passen: Tank 10 s und 60 s, Heiler 8 s und 90 s, Schaden 7 s und 45 s.",
