	["Error"] = "Fehler",
	["Error as GitHub issue"] = "Fehler als GitHub-Issue",
	["Errors and help"] = "Fehler und Hilfe",
	["Esc"] = "Esc",
	["Esc cancels."] = "Esc bricht ab.",
	["Essential row"] = "Essenzielle Reihe",
	["Estimate from the current score: who reaches the limit first, and the final score."] = "Schätzung nach dem aktuellen Punktestand: wer das Limit zuerst erreicht und der Endstand.",
	["Estimate rested XP"] = "Erholungsbonus schätzen",
	["Estimated time until the rested bar is full."] = "Geschätzte Zeit, bis die Erholungsleiste voll ist.",
	["Evade"] = "Entkommen",
	["Events"] = "Ereignisse",
	["Events beyond the window wait in a small grid at the far end."] = "Ereignisse jenseits des Fensters warten in einem kleinen Raster am anderen Ende.",
	["Every Classic dungeon with its packs (count on the marker, gold ring: elite), patrol paths, bosses (red, in kill order) and a route of numbered pulls."] = "Jeder Classic-Dungeon mit seinen Gegnergruppen (Anzahl auf der Markierung, goldener Ring: Elite), Patrouillenwegen, Bossen (rot, in Kill-Reihenfolge) und einer Route aus nummerierten Pulls.",
	["Every Legacy Challenge."] = "Jede Vermächtnis-Herausforderung.",
	["Every Legacy tree."] = "Jeder Vermächtnisbaum.",
	["Every alarm on with the chicken alarm, an oh no and a squeaky toy, and the flash."] = "Alle Alarme an, mit dem Hühneralarm, einem Oh nein und einem Quietschspielzeug, dazu das Aufblitzen.",
	["Every alarm on, EldoUI's alarm, chime and warning tones, and the red edge flash."] = "Alle Alarme an, EldoUIs Alarm-, Glocken- und Warntöne und das rote Randblitzen.",
	["Every announced death"] = "Jeder gemeldete Tod",
	["Every bar I use"] = "Alle von mir genutzten Leisten",
	["Every bar in the EldoUI accent color; the faction shows on the icon border."] = "Jede Leiste in der EldoUI-Akzentfarbe; die Fraktion zeigt sich am Symbolrand.",
	["Every bar in the stack glides to its new value instead of jumping. The game animates the bar itself."] = "Jede Leiste im Stapel gleitet zu ihrem neuen Wert, statt zu springen. Das Spiel animiert die Leiste selbst.",
	["Every button goes back to the automatic pick, the mount button too."] = "Jede Schaltfläche kehrt zur automatischen Auswahl zurück, auch die Reittier-Schaltfläche.",
	["Every button stays on screen, grayed out when empty, the Hearthstone and mount too."] = "Jede Schaltfläche bleibt auf dem Bildschirm, ausgegraut, wenn leer, auch Ruhestein und Reittier.",
	["Every character"] = "Jeder Charakter",
	["Every character's mail with the days left, running auctions and bids."] = "Die Post jedes Charakters mit den verbleibenden Tagen, laufende Auktionen und Gebote.",
	["Every character's professions with skill, recipes and cooldowns, and the recipe list of each."] = "Die Berufe jedes Charakters mit Fertigkeit, Rezepten und Abklingzeiten sowie die Rezeptliste jedes Berufs.",
	["Every character's saved instances with boss progress and the time to reset."] = "Die gespeicherten Instanzen jedes Charakters mit Bossfortschritt und der Zeit bis zum Zurücksetzen.",
	["Every class but the shaman: one bar with the buffs you keep up (live, faded while missing), your key cooldowns and the reagents you spend. Click casts; right-click picks the spell and rank."] = "Jede Klasse außer dem Schamanen: eine Leiste mit den Stärkungszaubern, die Ihr aufrechterhaltet (aktiv, verblasst, solange sie fehlen), Euren wichtigen Abklingzeiten und den Reagenzien, die Ihr verbraucht. Klick wirkt; Rechtsklick wählt Zauber und Rang.",
	["Every counter on its own mover instead of one strip. Place them in move mode."] = "Jeder Zähler auf einem eigenen Verschiebefeld statt einer gemeinsamen Leiste. Platziert sie im Verschiebemodus.",
	["Every counter on its own mover, to place anywhere."] = "Jeder Zähler auf einem eigenen Verschiebefeld, frei platzierbar.",
	["Every critical hit your target takes, from anyone."] = "Jeder kritische Treffer, den Euer Ziel erleidet, von jedem.",
	["Every currency these characters hold."] = "Jede Währung, die diese Charaktere besitzen.",
	["Every datatext on a 24 px bar, gray labels and white values."] = "Jeder Datentext auf einer 24 px hohen Leiste, graue Beschriftungen und weiße Werte.",
	["Every datatext on the info bar."] = "Jeder Datentext auf der Infoleiste.",
	["Every datatext, labels in your class color and white values."] = "Jeder Datentext, Beschriftungen in Eurer Klassenfarbe und weiße Werte.",
	["Every death in the log."] = "Jeder Tod im Protokoll.",
	["Every detail: counts, elites, patrols, numbers and a medium line."] = "Jedes Detail: Anzahlen, Elite, Patrouillen, Nummern und eine mittlere Linie.",
	["Every dungeon, raid and battleground you entered, newest first."] = "Jeder Dungeon, Schlachtzug und jedes Schlachtfeld, die Ihr betreten habt, neueste zuerst.",
	["Every enemy plate"] = "Jede feindliche Plakette",
	["Every game setting (CVar)"] = "Jede Spieleinstellung (CVar)",
	["Every goal is done."] = "Alle Ziele sind erledigt.",
	["Every guide in the guide data."] = "Jeder Guide in den Guide-Daten.",
	["Every herb, ore, chest and fishing pool you gather shows on the world map and minimap; finds close together are one node. Also: /eui gather."] = "Jedes Kraut, Erz, jede Truhe und jeder Fischschwarm, die Ihr sammelt, erscheinen auf Weltkarte und Minikarte; nah beieinanderliegende Funde sind ein Vorkommen. Auch: /eui gather.",
	["Every hit your target takes, from anyone. The game doesn't say who hit, so this is not only your damage."] = "Jeder Treffer, den Euer Ziel erleidet, von jedem. Das Spiel sagt nicht, wer getroffen hat, daher ist das nicht nur Euer Schaden.",
	["Every icon border in your accent color, for a calm one-color bar."] = "Jeder Symbolrand in Eurer Akzentfarbe, für eine ruhige, einfarbige Leiste.",
	["Every integration on: layouts place the windows, Details gets the EldoUI frame and size, RestedXP offers the EldoUI theme."] = "Alle Integrationen an: Layouts platzieren die Fenster, Details erhält den EldoUI-Rahmen und die Größe, RestedXP bietet das EldoUI-Thema an.",
	["Every item can get an action again."] = "Jeder Gegenstand kann wieder eine Aktion erhalten.",
	["Every line with a keyword is also copied into an Alerts chat tab, with time, source and a clickable name, also from channels no tab shows. The tab flashes on new lines. Off by default."] = "Jede Zeile mit einem Stichwort wird auch in einen Chatreiter „Hinweise“ kopiert, mit Zeit, Quelle und anklickbarem Namen, auch aus Kanälen, die kein Reiter zeigt. Der Reiter blinkt bei neuen Zeilen. Standardmäßig aus.",
	["Every notice and every stat in the summary. Sharing stays off."] = "Jeder Hinweis und jeder Wert in der Zusammenfassung. Teilen bleibt aus.",
	["Every pip in your class color, or each pip in its own color (set below)."] = "Jeder Punkt in Eurer Klassenfarbe oder jeder in seiner eigenen Farbe (unten einstellbar).",
	["Every pip turns one color when all your combo points are filled, so a finisher at five points stands out."] = "Alle Punkte nehmen eine Farbe an, wenn alle Eure Kombopunkte gefüllt sind, damit ein Finishing Move bei fünf Punkten auffällt.",
	["Every quest in the logs once, with the characters that have it. * = ready to turn in."] = "Jede Quest in den Logs einmal, mit den Charakteren, die sie haben. * = abgabebereit.",
	["Every run, newest first."] = "Jeder Durchlauf, neueste zuerst.",
	["Every rune once in each row, column and block."] = "Jede Rune einmal in jeder Reihe, Spalte und jedem Block.",
	["Every running auction with its bid, buyout and time left."] = "Jede laufende Auktion mit Gebot, Sofortkauf und Restzeit.",
	["Every saved mail with sender, items, gold and the time until it is returned or deleted."] = "Jede gespeicherte Post mit Absender, Gegenständen, Gold und der Zeit, bis sie zurückgeschickt oder gelöscht wird.",
	["Every school in its own theme; other units arcane. Rising motes, light lines."] = "Jede Schule in ihrem eigenen Thema; andere Einheiten arkan. Aufsteigende Partikel, helle Linien.",
	["Every spell on your action bars already uses its highest rank."] = "Jeder Zauber auf Euren Aktionsleisten nutzt bereits seinen höchsten Rang.",
	["Everyone"] = "Alle",
	["Everything else"] = "Alles andere",
	["Everything is selected. Press Ctrl+C and share it. It holds your own categories and the order of the sections."] = "Alles ist ausgewählt. Drückt Strg+C und teilt es. Es enthält Eure eigenen Kategorien und die Reihenfolge der Abschnitte.",
	["Everything saved about the character: level, gold, played, rested, professions, lockouts, mail and stats."] = "Alles Gespeicherte über den Charakter: Stufe, Gold, Spielzeit, Erholung, Berufe, Instanzsperren, Post und Werte.",
	["Exact played time at each level"] = "Exakte Spielzeit bei jeder Stufe",
	["Exact words only"] = "Nur exakte Wörter",
	["Expected winner"] = "Erwarteter Sieger",
	["Expected worth of the materials from disenchanting a green, blue or purple item, at your saved auction prices. Shows only once you have prices for those materials."] = "Erwarteter Wert der Materialien aus dem Entzaubern eines grünen, blauen oder lila Gegenstands, zu Euren gespeicherten Auktionspreisen. Erscheint erst, wenn Ihr Preise für diese Materialien habt.",
	["Experience divided by the time inside."] = "Erfahrung geteilt durch die Zeit drinnen.",
	["Experience from kills, from the game's chat line."] = "Erfahrung aus Kills, aus der Chatzeile des Spiels.",
	["Experience from kills, quests and exploring, added up in one row."] = "Erfahrung aus Kills, Quests und Erkundung, in einer Zeile zusammengezählt.",
