	["Experience through the current level."] = "Erfahrung in der aktuellen Stufe.",
	["Experience, XP per hour, kills and runs to the next level after each run."] = "Erfahrung, EP pro Stunde, Kills und Durchläufe bis zur nächsten Stufe nach jedem Durchlauf.",
