	["Final sound"] = "Letzter Ton",
	["Find"] = "Suchen",
	["Find a name, zone or cause. Press Enter; an empty search shows all."] = "Sucht einen Namen, ein Gebiet oder eine Ursache. Drückt die Eingabetaste; eine leere Suche zeigt alles.",
	["Find an item on any of your characters: bags, bank, gear, mail, auctions and guild banks."] = "Findet einen Gegenstand auf einem Eurer Charaktere: Taschen, Bank, Ausrüstung, Post, Auktionen und Gildenbanken.",
	["Find and sink the hidden Horde fleet before it sinks yours."] = "Findet und versenkt die verborgene Flotte der Horde, bevor sie Eure versenkt.",
	["Find on the chat's side rail (or /eui chatsearch) lists matching lines. Click a result to scroll to it; Copy results gives them as text."] = "Suchen an der Seitenleiste des Chats (oder /eui chatsearch) listet passende Zeilen auf. Klickt auf ein Ergebnis, um dorthin zu scrollen; Ergebnisse kopieren gibt sie als Text aus.",
	["Find the hidden five-letter word in six guesses, in English or in Danish."] = "Findet das verborgene Wort mit fünf Buchstaben in sechs Versuchen, auf Englisch oder Dänisch.",
