	["Font size of Blizzard's combat text. Game keeps Blizzard's size."] = "Schriftgröße von Blizzards Kampftext. Spiel behält Blizzards Größe.",
	["Font size of charges and stacks."] = "Schriftgröße von Aufladungen und Stapeln.",
	["Font size of the charges left (poisons, stones) on the icon."] = "Schriftgröße der verbleibenden Aufladungen (Gifte, Steine) auf dem Symbol.",
	["Font size of the cooldown countdown."] = "Schriftgröße des Abklingzeit-Countdowns.",
	["Font size of the effect name. Game keeps Blizzard's size."] = "Schriftgröße des Effektnamens. Spiel behält Blizzards Größe.",
