	["Hide off hand"] = "Schildhand ausblenden",
	["Hide one player in one public channel only. Whispers, guild and group chat and your /ignore list stay as they are. Right-click a sender in a channel line to mute them there."] = "Blendet einen Spieler nur in einem öffentlichen Kanal aus. Flüstern, Gilden- und Gruppenchat sowie Eure /ignore-Liste bleiben, wie sie sind. Rechtsklickt in einer Kanalzeile auf einen Absender, um ihn dort stummzuschalten.",
	["Hide other players' crafting"] = "Herstellung anderer Spieler ausblenden",
	["Hide quest timer"] = "Questtimer ausblenden",
	["Hide ranged"] = "Distanz ausblenden",
	["Hide repeated lines"] = "Wiederholte Zeilen ausblenden",
	["Hide runs older than a day."] = "Durchläufe ausblenden, die älter als ein Tag sind.",
	["Hide say and yell"] = "Sagen und Schreien ausblenden",
	["Hide small numbers"] = "Kleine Zahlen ausblenden",
