	["Hide the combo points with no target or no points."] = "Blendet die Kombopunkte ohne Ziel oder ohne Punkte aus.",
	["Hide the decorative frame around the zone ability; the button stays."] = "Blendet den Zierrahmen um die Zonenfähigkeit aus; die Taste bleibt.",
	["Hide the global cooldown"] = "Globale Abklingzeit ausblenden",
	["Hide the list while no enemies are listed."] = "Blendet die Liste aus, solange keine Gegner gelistet sind.",
	["Hide the parts checked below."] = "Blendet die unten angehakten Teile aus.",
	["Hide the personal resource display"] = "Persönliche Ressourcenanzeige ausblenden",
	["Hide the power bar while your mana or energy is full. While the game keeps your power secret (in some fights) the bar stays shown."] = "Blendet die Ressourcenleiste aus, solange Euer Mana oder Eure Energie voll ist. Solange das Spiel Eure Ressource geheim hält (in manchen Kämpfen), bleibt die Leiste sichtbar.",
	["Hide the side bar"] = "Seitenleiste ausblenden",
	["Hide the timers checked below."] = "Blendet die unten angehakten Timer aus.",
	["Hide the viewers checked under \"Hide this viewer\"."] = "Blendet die Anzeigen aus, die unter „Diese Anzeige ausblenden“ angehakt sind.",
	["Hide their chat bubbles"] = "Ihre Sprechblasen ausblenden",
	["Hide this bar while it is full. While the game keeps the value secret the bar stays shown."] = "Blendet diese Leiste aus, solange sie voll ist. Solange das Spiel den Wert geheim hält, bleibt die Leiste sichtbar.",
	["Hide this section"] = "Diesen Abschnitt ausblenden",
	["Hide this viewer"] = "Diese Anzeige ausblenden",
