	["Hide what you can't collect"] = "Nicht Sammelbares ausblenden",
	["Hide when EldoUI replaces it"] = "Ausblenden, wenn EldoUI es ersetzt",
	["Hide when empty"] = "Ausblenden, wenn leer",
	["Hide when full"] = "Ausblenden, wenn voll",
	["Hide whole guilds you don't want to read, without /ignore. Only what you see changes; your ignore list is untouched."] = "Blendet ganze Gilden aus, die Ihr nicht lesen wollt, ohne /ignore. Nur was Ihr seht, ändert sich; Eure Ignorierliste bleibt unberührt.",
	["Hide with gamepad"] = "Mit Gamepad ausblenden",
	["Hides boss and other timers shorter than this many seconds. The pull and the ready check always show."] = "Blendet Boss- und andere Timer aus, die kürzer als so viele Sekunden sind. Pull und Bereitschaftscheck werden immer angezeigt.",
	["Hides lines that contain Cyrillic letters. It looks at the letters, not the language. Off by default."] = "Blendet Zeilen aus, die kyrillische Buchstaben enthalten. Es achtet auf die Buchstaben, nicht auf die Sprache. Standardmäßig aus.",
	["Hides numbers below this. Numbers the game keeps hidden in a fight always show."] = "Blendet Zahlen darunter aus. Zahlen, die das Spiel im Kampf verborgen hält, werden immer angezeigt.",
	["Hides the ghost button. You can still return to the graveyard from the spirit healer."] = "Blendet die Geisterschaltfläche aus. Ihr könnt trotzdem über den Geistheiler zum Friedhof zurückkehren.",
	["Hides the guide window for this character. /eui eldostar show brings it back."] = "Blendet das Guide-Fenster für diesen Charakter aus. /eui eldostar show holt es zurück.",
	["Hides this area while you are in a party or raid."] = "Blendet diesen Bereich aus, solange Ihr in einer Gruppe oder einem Schlachtzug seid.",
	["High"] = "Hoch",
	["High (default)"] = "Hoch (Standard)",
	["Highest threat"] = "Höchste Bedrohung",
	["Highlight color"] = "Hervorhebungsfarbe",
