	["History and search"] = "Verlauf und Suche",
	["History from %s"] = "Verlauf vom %s",
	["Hit"] = "Treffer",
	["Hit numbers on plates are on, so Blizzard's damage numbers left at \"Blizzard setting\" stay off: one number per hit."] = "Trefferzahlen auf Namensplaketten sind an, daher bleiben Blizzards Schadenszahlen, die auf „Blizzard-Einstellung“ stehen, aus: eine Zahl pro Treffer.",
	["Hit the gnolls as they pop up, and leave the gnome alone."] = "Haut die Gnolle, wenn sie auftauchen, und lasst den Gnom in Ruhe.",
	["Hits on enemy plates"] = "Treffer auf gegnerischen Namensplaketten",
	["Hits on target"] = "Treffer am Ziel",
	["Hits that are fully blocked, absorbed or resisted."] = "Treffer, die vollständig geblockt, absorbiert oder widerstanden werden.",
	["Hits you take."] = "Treffer, die Ihr erleidet.",
	["Hits your pet takes."] = "Treffer, die Euer Begleiter erleidet.",
	["Hold"] = "Halten",
	["Hold %s over an item Bag Actions can use: the help shows there."] = "Haltet %s gedrückt und zeigt auf einen Gegenstand, den Taschenaktionen nutzen kann: Dort erscheint die Hilfe.",
	["Hold Shift and drag anywhere on a bar or panel to move it. Saved like move mode; not in combat."] = "Haltet Umschalt gedrückt und zieht an einer beliebigen Stelle einer Leiste oder eines Panels, um es zu verschieben. Wird wie im Verschiebemodus gespeichert; nicht im Kampf.",
	["Hold Shift, Ctrl or Alt to see just those clicks; no modifier shows plain clicks."] = "Haltet Umschalt, Strg oder Alt gedrückt, um nur diese Klicks zu sehen; ohne Zusatztaste erscheinen die einfachen Klicks.",
	["Hold a modifier key over an item in your bags and click it to disenchant, prospect, mill or pick its lock. One click casts one spell on one item."] = "Haltet eine Zusatztaste gedrückt, zeigt auf einen Gegenstand in Euren Taschen und klickt ihn an, um ihn zu entzaubern, zu sondieren, zu mahlen oder sein Schloss zu knacken. Ein Klick wirkt einen Zauber auf einen Gegenstand.",
	["Hold the modifier and point at an item: a glow shows when you can break or open it, and your click casts that spell on it. Not in combat."] = "Haltet die Zusatztaste gedrückt und zeigt auf einen Gegenstand: Ein Leuchten zeigt, wann Ihr ihn zerlegen oder öffnen könnt, und Euer Klick wirkt diesen Zauber darauf. Nicht im Kampf.",
	["Hold this key (and no other) over an item to get the action. Alt-click still attaches items while the mailbox is open."] = "Haltet diese Taste (und keine andere) über einem Gegenstand, um die Aktion zu erhalten. Alt-Klick hängt weiterhin Gegenstände an, solange der Briefkasten offen ist.",
	["Holy"] = "Heilig",
	["Holy for other units, golden motes and a bright finish."] = "Heilig für andere Einheiten, goldene Funken und ein heller Abschluss.",
	["Home"] = "Heim",
	["Home: chat and your realm. World: combat and the world around you."] = "Heim: Chat und Euer Realm. Welt: Kampf und die Welt um Euch herum.",
	["Honor"] = "Ehre",
	["Honor and honorable kills in a battleground."] = "Ehre und ehrenhafte Siege auf einem Schlachtfeld.",
	["Honor gained"] = "Erhaltene Ehre",
	["Honor gains"] = "Ehregewinn",
	["Honor you gain, from the game's chat line."] = "Ehre, die Ihr erhaltet, aus der Chatzeile des Spiels.",
	["Honor you gain."] = "Ehre, die Ihr erhaltet.",
	["Honorable kill"] = "Ehrenhafter Sieg",
	["Honorable kills"] = "Ehrenhafte Siege",
	["Hop a murloc over the road and the river into the five nests."] = "Lasst einen Murloc über die Straße und den Fluss in die fünf Nester hüpfen.",
	["Horde ships sunk: %d of %d"] = "Hordeschiffe versenkt: %d von %d",
	["Horde waters"] = "Gewässer der Horde",
	["Horde wins 2000-1430"] = "Horde gewinnt 2000-1430",
	["Horizontal fits the layout spot. Vertical has no layout spot: drag it in move mode."] = "Horizontal passt zum Platz im Layout. Vertikal hat keinen Platz im Layout: Zieht es im Verschiebemodus.",
	["Horizontal shift of the time text."] = "Horizontale Verschiebung des Zeittexts.",
	["Horse"] = "Pferd",
	["Hourly limit"] = "Stundenlimit",
	["Hourly limit set to %d."] = "Stundenlimit auf %d gesetzt.",
	["Hover a campfire first."] = "Zeigt zuerst auf ein Lagerfeuer.",
	["Hover a frame to see every click in its tooltip."] = "Zeigt auf einen Rahmen, um jeden Klick in seinem Tooltip zu sehen.",
	["Hover a trinket or ring slot to see the matching items in your bags, and click one to wear it there. Out of combat only. Blizzard's own Alt flyout keeps working."] = "Zeigt auf einen Schmuck- oder Ringplatz, um die passenden Gegenstände in Euren Taschen zu sehen, und klickt einen an, um ihn dort anzulegen. Nur außerhalb des Kampfes. Blizzards eigenes Alt-Ausklappmenü funktioniert weiterhin.",
	["Hover any EldoUI button and press a key to bind it."] = "Zeigt auf eine beliebige Aktionstaste von EldoUI und drückt eine Taste, um sie zu belegen.",
	["Hovering a campfire shows its tier, slots and the features you have seen; hovering a feature shows its buff and whether you have it."] = "Zeigt Ihr auf ein Lagerfeuer, seht Ihr seine Stufe, seine Plätze und die Merkmale, die Ihr gesehen habt; auf einem Merkmal seht Ihr seinen Stärkungszauber und ob Ihr ihn habt.",
	["Hovering a frame lists your bindings in the tooltip, grouped by modifier: the game's Click Casting and EldoUI's."] = "Zeigt Ihr auf einen Rahmen, listet der Tooltip Eure Belegungen nach Zusatztaste gruppiert: die Klickzauber des Spiels und die von EldoUI.",
	["How Blizzard's combat text around your character moves (Blizzard's option floatingCombatTextFloatMode)."] = "Wie sich Blizzards Kampftext um Euren Charakter bewegt (Blizzards Option floatingCombatTextFloatMode).",
	["How a button shows that it is pressed."] = "Wie eine Aktionstaste zeigt, dass sie gedrückt ist.",
	["How a button shows that its spell has procced. The look of \"As set\" is the \"Action bar procs\" row on the Glows page. The game says which spell; EldoUI only draws it."] = "Wie eine Aktionstaste zeigt, dass ihr Zauber ausgelöst wurde (Proc). Die Optik von „Wie eingestellt“ ist die Zeile „Procs auf Aktionsleisten“ auf der Seite Leuchteffekte. Das Spiel sagt, welcher Zauber es ist; EldoUI zeichnet nur.",
	["How a button shows that the mouse is over it."] = "Wie eine Aktionstaste zeigt, dass die Maus darüber ist.",
	["How a button shows that the target is out of range."] = "Wie eine Aktionstaste zeigt, dass das Ziel außer Reichweite ist.",
	["How a crafted item's or recipe's tooltip lists the guild members who know it. The Loot Guide's Crafting page uses the same form."] = "Wie der Tooltip eines hergestellten Gegenstands oder Rezepts die Gildenmitglieder auflistet, die es kennen. Die Seite Handwerk des Loot Guides verwendet dieselbe Form.",
	["How a dashboard looks with sample values, in your art style and accent."] = "Wie ein Dashboard mit Beispielwerten aussieht, in Eurem Grafikstil und Eurer Akzentfarbe.",
	["How a spell with charges shows that a charge is coming back while you still have one: a light swipe, only the bright edge, or nothing."] = "Wie ein Zauber mit Aufladungen zeigt, dass eine Aufladung zurückkommt, während Ihr noch eine habt: eine leichte Spirale, nur der helle Rand oder nichts.",
	["How big the pulse icon is."] = "Wie groß das Pulssymbol ist.",
	["How bright the shine is."] = "Wie hell der Glanz ist.",
	["How clock times are written in the log. Like every EldoUI clock: the clock format on the General page."] = "Wie Uhrzeiten im Protokoll geschrieben werden. Wie jede Uhr von EldoUI: das Uhrzeitformat auf der Seite Allgemein.",
	["How close a result must be to what you typed. Close matches also find \"swgry\" for Swift Gryphon."] = "Wie nah ein Ergebnis an Eurer Eingabe sein muss. Ungefähre Treffer finden auch „rhstn“ für Ruhestein.",
	["How close an edge must come before it snaps, in pixels."] = "Wie nah eine Kante kommen muss, bevor sie einrastet, in Pixeln.",
	["How close to pulling aggro, in percent of the point where you would pull."] = "Wie nah Ihr daran seid, die Aggro zu ziehen, in Prozent des Punkts, an dem Ihr sie ziehen würdet.",
	["How critical hits and other sticky lines appear."] = "Wie kritische Treffer und andere haftende Zeilen erscheinen.",
	["How dark the bubble box is."] = "Wie dunkel der Kasten der Sprechblase ist.",
	["How dark the cooldown swipe over the icon is."] = "Wie dunkel die Abklingzeitspirale über dem Symbol ist.",
	["How dark the game world behind the panel gets."] = "Wie dunkel die Spielwelt hinter dem Panel wird.",
	["How dark the panel behind the chat is (panel mode only)."] = "Wie dunkel das Panel hinter dem Chat ist (nur im Panelmodus).",
	["How dark the swipe is."] = "Wie dunkel die Spirale ist.",
	["How dark this icon's shadow is."] = "Wie dunkel der Schatten dieses Symbols ist.",
	["How early the mail reminder warns."] = "Wie früh die Post-Erinnerung warnt.",
	["How early the warning comes."] = "Wie früh die Warnung kommt.",
	["How early, and for which kinds."] = "Wie früh und für welche Arten.",
	["How far ahead the bar looks. Events further out wait at the far end."] = "Wie weit die Leiste vorausschaut. Weiter entfernte Ereignisse warten am fernen Ende.",
	["How far the camera sits behind you. The camera stops at the max camera distance (Quality of Life > Sound and misc)."] = "Wie weit die Kamera hinter Euch sitzt. Die Kamera stoppt bei der maximalen Kameradistanz (Komfortfunktionen > Klang und Sonstiges).",
	["How far the icon overshoots before it settles (1 = no overshoot)."] = "Wie weit das Symbol überschießt, bevor es zur Ruhe kommt (1 = kein Überschießen).",
	["How far this icon's shadow reaches beyond its edge."] = "Wie weit der Schatten dieses Symbols über seinen Rand hinausreicht.",
	["How far up and down particles fan out, in degrees."] = "Wie weit Partikel nach oben und unten auffächern, in Grad.",
	["How far you can scroll back. Game keeps the game's default."] = "Wie weit Ihr zurückscrollen könnt. Spiel behält den Standard des Spiels.",
	["How fast every scroll area plays, in percent. Each area can override it."] = "Wie schnell jeder Scrollbereich abläuft, in Prozent. Jeder Bereich kann es überschreiben.",
	["How fast particles drift back along the bar, in pixels per second."] = "Wie schnell Partikel an der Leiste entlang zurücktreiben, in Pixeln pro Sekunde.",
	["How fast the action games run (Snake, Rune Stack, Gryphon Glide and Brick Breaker) and how long WoW Trivia gives you for each question."] = "Wie schnell die Actionspiele laufen (Snake, Runenstapel, Greifenflug und Mauerbrecher) und wie viel Zeit WoW-Quiz Euch für jede Frage gibt.",
	["How fast the camera turns."] = "Wie schnell sich die Kamera dreht.",
	["How fast the shine sweeps."] = "Wie schnell der Glanz darüberstreicht.",
	["How gold is written in the bag windows and their tooltips. \"Use general setting\" follows Fonts and text > Money."] = "Wie Gold in den Taschenfenstern und ihren Tooltips geschrieben wird. „Allgemeine Einstellung verwenden“ folgt Schriften und Text > Geld.",
	["How icons in EldoUI's rows look in each state the game reports: on cooldown, recharging, not usable or out of range."] = "Wie Symbole in den Reihen von EldoUI in jedem Zustand aussehen, den das Spiel meldet: in Abklingzeit, beim Aufladen, nicht nutzbar oder außer Reichweite.",
	["How long a character can stay away from the auction house before the reminder."] = "Wie lange ein Charakter dem Auktionshaus fernbleiben kann, bevor die Erinnerung kommt.",
	["How long a line stays before it fades."] = "Wie lange eine Zeile bleibt, bevor sie verblasst.",
	["How long a player stays listed after their nameplate went away."] = "Wie lange ein Spieler gelistet bleibt, nachdem seine Namensplakette verschwunden ist.",
	["How long a repeated line stays hidden."] = "Wie lange eine wiederholte Zeile ausgeblendet bleibt.",
	["How long a row of their loot stays."] = "Wie lange eine Zeile ihrer Beute bleibt.",
	["How long each card or row stays. Its time stops while the mouse is over it, and a right-click closes it."] = "Wie lange jede Karte oder Zeile bleibt. Ihre Zeit stoppt, solange die Maus darüber ist, und ein Rechtsklick schließt sie.",
	["How long the current fight has lasted, from Blizzard's damage meter session when it has one. The InfoBar's Combat time reads the same timer."] = "Wie lange der aktuelle Kampf schon dauert, aus der Sitzung von Blizzards Schadensmesser, wenn es eine gibt. Die Kampfzeit der Infoleiste liest denselben Timer.",
	["How long the fade itself takes."] = "Wie lange das Verblassen selbst dauert.",
	["How long the result stays when someone else won or everyone passed."] = "Wie lange das Ergebnis bleibt, wenn jemand anderes gewonnen hat oder alle gepasst haben.",
	["How long the result stays when you won the item."] = "Wie lange das Ergebnis bleibt, wenn Ihr den Gegenstand gewonnen habt.",
	["How long the roll window stays open without a new roll. It never closes while the mouse is over it. 0 keeps it open."] = "Wie lange das Würfelfenster ohne neuen Wurf offen bleibt. Es schließt sich nie, solange die Maus darüber ist. 0 hält es offen.",
	["How long the text stays before it fades."] = "Wie lange der Text bleibt, bevor er verblasst.",
	["How long the text stays. General uses the General tab's time."] = "Wie lange der Text bleibt. Allgemein verwendet die Zeit aus dem Reiter Allgemein.",
	["How long you were inside."] = "Wie lange Ihr drin wart.",
	["How looted items are valued. Auction prices are the ones EldoUI saved when you searched the auction house."] = "Wie geplünderte Gegenstände bewertet werden. Auktionspreise sind die, die EldoUI gespeichert hat, als Ihr das Auktionshaus durchsucht habt.",
	["How many boss auras at once."] = "Wie viele Bossauren gleichzeitig.",
	["How many buffs fit in one row."] = "Wie viele Stärkungszauber in eine Reihe passen.",
	["How many buttons the bar shows, up to nine. Keys 10 to 12 of the key sets use the Consumable Bar."] = "Wie viele Aktionstasten die Leiste zeigt, bis zu neun. Die Tasten 10 bis 12 der Tastensätze nutzen die Verbrauchsgüterleiste.",
	["How many buttons the bar shows."] = "Wie viele Aktionstasten die Leiste zeigt.",
	["How many classes can a new character choose from?"] = "Aus wie vielen Klassen kann ein neuer Charakter wählen?",
	["How many copper coins make one silver?"] = "Wie viele Kupfermünzen ergeben ein Silber?",
	["How many datatexts the panel has. The slots share its width (or height when vertical) evenly."] = "Wie viele Datentexte das Panel hat. Die Plätze teilen sich seine Breite (oder Höhe, wenn vertikal) gleichmäßig.",
	["How many debuffs fit in one row."] = "Wie viele Schwächungszauber in eine Reihe passen.",
	["How many fill particles start each second at intensity 100."] = "Wie viele Füllpartikel pro Sekunde bei Intensität 100 starten.",
	["How many icons at most."] = "Wie viele Symbole höchstens.",
	["How many in your group picked Need, Transmog, Greed or Pass so far, from the game's loot history, above the timer. Point at the counts for the names and who has not chosen yet."] = "Wie viele in Eurer Gruppe bisher Bedarf, Transmogrifikation, Gier oder Passen gewählt haben, aus dem Beuteverlauf des Spiels, über dem Timer. Zeigt auf die Zahlen für die Namen und wer noch nicht gewählt hat.",
	["How many letters the edit box takes while splitting is on (links count with their hidden part)."] = "Wie viele Zeichen das Eingabefeld annimmt, solange das Aufteilen an ist (Links zählen mit ihrem verborgenen Teil).",
	["How many minutes before the time the reminder prints."] = "Wie viele Minuten vor dem Zeitpunkt die Erinnerung ausgegeben wird.",
	["How many more runs like this one until you level up."] = "Wie viele weitere Durchläufe wie dieser bis zu Eurem nächsten Stufenaufstieg nötig sind.",
	["How many new instances the server lets you enter per hour. Change it if Forever uses a different limit."] = "Wie viele neue Instanzen der Server Euch pro Stunde betreten lässt. Ändert es, wenn Forever ein anderes Limit nutzt.",
	["How many of the item each of your characters has, per location (Bags module)."] = "Wie viele dieses Gegenstands jeder Eurer Charaktere hat, nach Ort (Modul Taschen).",
	["How many of the item you now have in your bags, on the row's icon."] = "Wie viele dieses Gegenstands Ihr jetzt in Euren Taschen habt, auf dem Symbol der Zeile.",
	["How many of the newest lines the list shows."] = "Wie viele der neuesten Zeilen die Liste zeigt.",
	["How many of the next pulls the card lists."] = "Wie viele der nächsten Pulls die Karte auflistet.",
	["How many of the reagents your class spends you carry, and a hunter's ammo."] = "Wie viele der Reagenzien, die Eure Klasse verbraucht, Ihr dabeihabt, und die Munition eines Jägers.",
	["How many of this reagent you carry."] = "Wie viele dieses Reagenzes Ihr dabeihabt.",
	["How many particles burst from the edge when a cast completes."] = "Wie viele Partikel vom Rand aufsprühen, wenn ein Zauber vollendet ist.",
	["How many particles start each second at intensity 100."] = "Wie viele Partikel pro Sekunde bei Intensität 100 starten.",
	["How many pet buttons show."] = "Wie viele Begleitertasten angezeigt werden.",
	["How many races can a new character choose from?"] = "Aus wie vielen Völkern kann ein neuer Charakter wählen?",
	["How many results the box shows at most."] = "Wie viele Ergebnisse das Feld höchstens zeigt.",
	["How many runs like this one a whole level takes."] = "Wie viele Durchläufe wie dieser eine ganze Stufe braucht.",
	["How many runs this log keeps (all characters). Older runs leave the log; My Adventure keeps every run in its journal, with who was in it."] = "Wie viele Durchläufe dieses Protokoll behält (alle Charaktere). Ältere Durchläufe verlassen das Protokoll; Mein Abenteuer behält jeden Durchlauf in seinem Tagebuch, mit allen, die dabei waren.",
	["How many sample frames the test shows. Also /eui grouptest raid20."] = "Wie viele Beispielrahmen der Test zeigt. Auch /eui grouptest raid20.",
	["How many saved sessions each zone keeps."] = "Wie viele gespeicherte Sitzungen jedes Gebiet behält.",
	["How many seconds before the event the big icon appears."] = "Wie viele Sekunden vor dem Ereignis das große Symbol erscheint.",
	["How many silver coins make one gold?"] = "Wie viele Silbermünzen ergeben ein Gold?",
	["How many stacks fill the bar. Set it to the aura's most stacks."] = "Wie viele Stapel die Leiste füllen. Stellt es auf die maximale Stapelzahl der Aura ein.",
	["How many texts can wait while one shows. Extra ones are skipped."] = "Wie viele Texte warten können, während einer angezeigt wird. Weitere werden übersprungen.",
	["How many timer bars at most."] = "Wie viele Timerleisten höchstens.",
	["How many toast cards show at once. More wait their turn, and cards for loot in combat wait until the fight ends. The Loot Toasts mover is as tall as these cards."] = "Wie viele Hinweiskarten gleichzeitig erscheinen. Weitere warten, bis sie dran sind, und Karten für Beute im Kampf warten bis zum Ende des Kampfes. Das Verschiebefeld Beutehinweise ist so hoch wie diese Karten.",
	["How many waiting icons show before a +N count."] = "Wie viele wartende Symbole vor einer +N-Zahl angezeigt werden.",
	["How many whispers arrived while you were away. Read them in chat when you're back."] = "Wie viele Flüsternachrichten eingetroffen sind, während Ihr weg wart. Lest sie im Chat, wenn Ihr zurück seid.",
	["How much below the cheapest current price the Quick Sell tab starts."] = "Wie weit unter dem günstigsten aktuellen Preis der Reiter Schnellverkauf beginnt.",
	["How much below the cheapest current price the Quick Sell tab starts. 100 copper = 1 silver."] = "Wie weit unter dem günstigsten aktuellen Preis der Reiter Schnellverkauf beginnt. 100 Kupfer = 1 Silber.",
	["How much of each icon edge is cut away, in percent. 8 is EldoUI's default."] = "Wie viel von jedem Symbolrand abgeschnitten wird, in Prozent. 8 ist der Standard von EldoUI.",
	["How much of the art's edge is cut off, in percent."] = "Wie viel vom Rand der Grafik abgeschnitten wird, in Prozent.",
	["How normal lines move: straight, arc, angled, fountain, or stacked in place."] = "Wie sich normale Zeilen bewegen: gerade, im Bogen, schräg, als Fontäne oder an Ort und Stelle gestapelt.",
	["How numbered channels are shortened."] = "Wie nummerierte Kanäle abgekürzt werden.",
	["How numbers are written. Works for numbers the game keeps hidden in a fight too."] = "Wie Zahlen geschrieben werden. Funktioniert auch für Zahlen, die das Spiel im Kampf verborgen hält.",
	["How plate numbers are colored. School colors need the game to say the school."] = "Wie Zahlen auf Namensplaketten gefärbt werden. Für Schulfarben muss das Spiel die Schule nennen.",
	["How plate numbers move."] = "Wie sich Zahlen auf Namensplaketten bewegen.",
	["How see-through the background is."] = "Wie durchsichtig der Hintergrund ist.",
	["How see-through the route line and patrol paths are."] = "Wie durchsichtig die Routenlinie und die Patrouillenwege sind.",
	["How small the icon starts before it pops in (1 = full size)."] = "Wie klein das Symbol beginnt, bevor es aufploppt (1 = volle Größe).",
	["How solid the marks are."] = "Wie deckend die Markierungen sind.",
	["How solid the pins are."] = "Wie deckend die Kartenmarkierungen sind.",
	["How strong the flash is."] = "Wie stark das Aufblitzen ist.",
	["How strongly the bar's edges light up in this theme."] = "Wie stark die Ränder der Leiste in diesem Theme aufleuchten.",
	["How strongly the image shows through."] = "Wie stark das Bild durchscheint.",
	["How the Date datatext writes the date."] = "Wie der Datentext Datum das Datum schreibt.",
	["How the Gold datatext shows your money."] = "Wie der Datentext Gold Euer Geld anzeigt.",
	["How the Quick Sell tab lowers the cheapest current price. The price never goes below the vendor price."] = "Wie der Reiter Schnellverkauf den günstigsten aktuellen Preis senkt. Der Preis fällt nie unter den Händlerpreis.",
	["How the line reads. Codes filled in by the game: {amount} {name} {spell} {type} {count} {item} {total} {text}."] = "Wie die Zeile lautet. Codes, die das Spiel ausfüllt: {amount} {name} {spell} {type} {count} {item} {total} {text}.",
	["How the mark looks: a check, a question mark or a cross; a small colored square; or a short word (New, Look, Have)."] = "Wie die Markierung aussieht: ein Haken, ein Fragezeichen oder ein Kreuz; ein kleines farbiges Quadrat; oder ein kurzes Wort (Neu, Optik, Vorhanden).",
	["How the selected tab is marked."] = "Wie der gewählte Reiter markiert wird.",
	["How the text appears."] = "Wie der Text erscheint.",
	["How the text appears. With Animations off (General page) it just shows."] = "Wie der Text erscheint. Mit ausgeschalteten Animationen (Seite Allgemein) erscheint er einfach.",
	["How the text comes in: all at once, or a sentence at a time, fast or slow. A click on the text or Space shows all of it."] = "Wie der Text erscheint: auf einmal oder satzweise, schnell oder langsam. Ein Klick auf den Text oder die Leertaste zeigt alles.",
	["How the text is colored. By type: damage red, healing green, misses white."] = "Wie der Text gefärbt wird. Nach Art: Schaden rot, Heilung grün, Fehlschläge weiß.",
	["How the time left is shown."] = "Wie die Restzeit angezeigt wird.",
	["How the time left is shown. The game formats it; EldoUI never reads the time."] = "Wie die Restzeit angezeigt wird. Das Spiel formatiert sie; EldoUI liest die Zeit nie.",
	["How the time left is written. The game formats it; EldoUI only picks the format."] = "Wie die Restzeit geschrieben wird. Das Spiel formatiert sie; EldoUI wählt nur das Format.",
	["How the time left shows on the icons."] = "Wie die Restzeit auf den Symbolen erscheint.",
	["How times are written in the log, tooltips and chat lines."] = "Wie Zeiten im Protokoll, in Tooltips und in Chatzeilen geschrieben werden.",
	["How triggers with a flash light up the screen. Capped for comfort: at most one flash every half second."] = "Wie Auslöser mit Aufblitzen den Bildschirm erhellen. Zur Schonung begrenzt: höchstens ein Aufblitzen pro halbe Sekunde.",
	["How visible DBM's bars stay."] = "Wie sichtbar die Leisten von DBM bleiben.",
	["How visible a faded bar is."] = "Wie sichtbar eine verblasste Leiste ist.",
	["How visible a missing aura's icon is."] = "Wie sichtbar das Symbol einer fehlenden Aura ist.",
	["How visible an icon is while its spell or item is on cooldown. 100 = fully visible."] = "Wie sichtbar ein Symbol ist, solange sein Zauber oder Gegenstand Abklingzeit hat. 100 = voll sichtbar.",
	["How visible an icon is while the game says you can't cast it (not enough mana, rage or energy, or a missing requirement)."] = "Wie sichtbar ein Symbol ist, solange das Spiel sagt, dass Ihr es nicht wirken könnt (nicht genug Mana, Wut oder Energie oder eine fehlende Voraussetzung).",
	["How visible the idle edit box stays. 0 is invisible until you point at it or type."] = "Wie sichtbar das ruhende Eingabefeld bleibt. 0 ist unsichtbar, bis Ihr darauf zeigt oder tippt.",
	["Hunter"] = "Jäger",
	["Hunters: one message and sound when ammo drops below the amount below, again only after restocking."] = "Jäger: eine Nachricht und ein Klang, wenn die Munition unter die Menge unten fällt, erneut erst nach dem Auffüllen.",
	["Hybrid (druid)"] = "Hybrid (Druide)",
	["I died at level %d in %s."] = "Ich bin auf Stufe %d in %s gestorben.",
	["I died at level %d."] = "Ich bin auf Stufe %d gestorben.",
	["Icon Mahjong"] = "Symbol-Mahjong",
	["Icon art"] = "Symbolgrafik",
	["Icon border"] = "Symbolrand",
	["Icon picked. Its settings are in %s > Cooldown Manager."] = "Symbol gewählt. Seine Einstellungen findet Ihr unter %s > Abklingzeitenmanager.",
	["Icon pop"] = "Symbol einblenden",
	["Icon size"] = "Symbolgröße",
	["Icon size, capped by the frame height."] = "Symbolgröße, begrenzt durch die Rahmenhöhe.",
	["Icon tiles"] = "Symbolkacheln",
	["Icon zoom"] = "Symbolzoom",
	["Icons"] = "Symbole",
	["Icons before names"] = "Symbole vor Namen",
	["Icons in %s"] = "Namenssymbole: %s",
	["Icons in EldoUI's cooldown rows while the game says the spell is off cooldown. Off by default."] = "Symbole in den Abklingzeitreihen von EldoUI, solange das Spiel sagt, dass der Zauber keine Abklingzeit hat. Standardmäßig aus.",
	["Icons in EldoUI's cooldown rows whose spell the game lights up (a proc or a reactive spell). Only the game's own spell alert starts it."] = "Symbole in den Abklingzeitreihen von EldoUI, deren Zauber das Spiel aufleuchten lässt (ein Proc oder ein reaktiver Zauber). Nur die eigene Zauberwarnung des Spiels startet es.",
	["Icons in one line before a new one starts."] = "Symbole in einer Zeile, bevor eine neue beginnt.",
	["Icons in one row (or bars in one column) before a new one starts."] = "Symbole in einer Reihe (oder Leisten in einer Spalte), bevor eine neue beginnt.",
	["Icons in one row (or column) before a new one starts."] = "Symbole in einer Reihe (oder Spalte), bevor eine neue beginnt.",
	["Icons in one row before a new one starts."] = "Symbole in einer Reihe, bevor eine neue beginnt.",
	["Icons in rows, or one timer bar per aura with its icon, name and time."] = "Symbole in Reihen oder eine Timerleiste pro Aura mit Symbol, Name und Zeit.",
	["Icons in your aura groups while the game marks the aura as safe to refresh early. Only auras the game marks ever glow."] = "Symbole in Euren Aurengruppen, solange das Spiel die Aura als früh erneuerbar markiert. Nur Auren, die das Spiel markiert, leuchten überhaupt.",
	["Icons on item and spell links"] = "Symbole an Gegenstands- und Zauberlinks",
	["Icons only"] = "Nur Symbole",
	["Icons per line"] = "Symbole pro Zeile",
	["Icons per row"] = "Symbole pro Reihe",
	["Icons right"] = "Symbole rechts",
	["Icons show only while the aura is on; nothing marks a missing one."] = "Symbole erscheinen nur, solange die Aura aktiv ist; nichts markiert eine fehlende.",
	["Icons slide to their new spot instead of jumping when an icon hides, shows or is dragged. With animations off (General) they jump."] = "Symbole gleiten an ihren neuen Platz, statt zu springen, wenn ein Symbol aus- oder eingeblendet oder gezogen wird. Mit ausgeschalteten Animationen (Allgemein) springen sie.",
	["Icons that would touch split into an upper and a lower lane, so none hides another. Off keeps one line at full size. Either way, an icon with no room moves on a little and shows its seconds."] = "Symbole, die sich berühren würden, teilen sich in eine obere und eine untere Spur auf, sodass keins ein anderes verdeckt. Aus behält eine Linie in voller Größe. So oder so rückt ein Symbol ohne Platz etwas weiter und zeigt seine Sekunden.",
	["Icons travel toward the other end: right on a horizontal bar, top on a vertical one."] = "Symbole wandern zum anderen Ende: nach rechts auf einer horizontalen Leiste, nach oben auf einer vertikalen.",
	["Icons, or timer bars with the spell's icon, name and time. The game runs the time."] = "Symbole oder Timerleisten mit Symbol, Name und Zeit des Zaubers. Das Spiel führt die Zeit.",
	["Id, name and source. Use the id with /eui sound."] = "ID, Name und Quelle. Nutzt die ID mit /eui sound.",
	["If missing, play"] = "Falls fehlend, abspielen",
	["Ignore when sorting"] = "Beim Sortieren ignorieren",
	["Image file"] = "Bilddatei",
	["Image opacity"] = "Bilddeckkraft",
	["Immune"] = "Immun",
	["Imp"] = "Wichtel",
	["Import a Legacy build"] = "Einen Vermächtnis-Build importieren",
	["Import a dungeon route"] = "Eine Dungeonroute importieren",
	["Import a route"] = "Eine Route importieren",
	["Import a shopping list"] = "Eine Einkaufsliste importieren",
	["Import gathering nodes"] = "Sammelvorkommen importieren",
	["Import nodes"] = "Vorkommen importieren",
	["Import this spec's set"] = "Satz dieser Spezialisierung importieren",
	["Imported %d bag categories."] = { one = "%d Taschenkategorie importiert.", other = "%d Taschenkategorien importiert." },
	["Imported %d search terms."] = "%d Suchbegriffe importiert.",
	["Imported route"] = "Importierte Route",
	["Imports EldoUI's Details profile for this layout through Details' own import, as \"EldoUI - <layout>\", and switches Details to it. Your own Details profiles stay in its list. Not in combat."] = "Importiert das Details-Profil von EldoUI für dieses Layout über den eigenen Import von Details als \"EldoUI - <layout>\" und schaltet Details darauf um. Eure eigenen Details-Profile bleiben in seiner Liste. Nicht im Kampf.",
	["Improve: turn on the game's buff duration display."] = "Verbessern: schaltet die Anzeige der Dauer von Stärkungszaubern im Spiel ein.",
	["In Alterac Valley, a small marker per mine in its owner's color."] = "Im Alteractal eine kleine Markierung pro Mine in der Farbe ihres Besitzers.",
	["In Alterac Valley, shows how many hand-in items you carry and who takes them. It never hands them in for you."] = "Zeigt im Alteractal, wie viele Abgabegegenstände Ihr dabeihabt und wer sie annimmt. Es gibt sie nie für Euch ab.",
	["In a battleground the main bar's center shows your score and the fight time instead of its usual blocks."] = "Auf einem Schlachtfeld zeigt die Mitte der Hauptleiste Euren Punktestand und die Kampfzeit statt ihrer üblichen Blöcke.",
	["In a party"] = "In einer Gruppe",
	["In a raid"] = "In einem Schlachtzug",
	["In combat the game hides some stats from addons; they show \"%s\" until the fight ends."] = "Im Kampf verbirgt das Spiel einige Werte vor Addons; sie zeigen \"%s\", bis der Kampf endet.",
	["In combat: only results that need no secure click."] = "Im Kampf: nur Ergebnisse, die keinen geschützten Klick brauchen.",
	["In fishing mode, out of combat, the second of two quick right-clicks casts Fishing."] = "Im Angelmodus außerhalb des Kampfes wirkt der zweite von zwei schnellen Rechtsklicks Angeln.",
	["In groups too"] = "Auch in Gruppen",
	["In hand: you %d, the Horde %d"] = "Auf der Hand: Ihr %d, die Horde %d",
	["In its last seconds the next event moves off the bar into a big icon at the bar's now end."] = "In seinen letzten Sekunden wandert das nächste Ereignis von der Leiste in ein großes Symbol am Jetzt-Ende der Leiste.",
	["In log"] = "Im Log",
	["In public channels, say and yell: the same text from the same player within the time below shows only once. Off by default."] = "In öffentlichen Kanälen, bei Sagen und Schreien: Derselbe Text vom selben Spieler innerhalb der Zeit unten erscheint nur einmal. Standardmäßig aus.",
	["In the bag window"] = "Im Taschenfenster",
	["In the bank window"] = "Im Bankfenster",
	["In the chat window (top edge)"] = "Im Chatfenster (Oberkante)",
	["In the chat window the bar is as wide as the chat."] = "Im Chatfenster ist die Leiste so breit wie der Chat.",
	["In the chat window: the bar fills the top edge of the chat box, as wide as the chat, and the messages and docked panels make room. Its own mover: drag it in move mode."] = "Im Chatfenster: Die Leiste füllt die Oberkante des Chatfelds, so breit wie der Chat, und die Nachrichten und angedockten Panels machen Platz. Eigenes Verschiebefeld: Zieht es im Verschiebemodus.",
	["In the stack"] = "Im Stapel",
	["In the stack with the other bars, or on its own mover (Resource Bar %d in move mode)."] = "Im Stapel mit den anderen Leisten oder auf einem eigenen Verschiebefeld (Ressourcenleiste %d im Verschiebemodus).",
	["In which battleground do the Stormpike Guard and the Frostwolf Clan fight?"] = "Auf welchem Schlachtfeld kämpfen die Sturmlanzengarde und der Frostwolfklan?",
	["In which battleground do you capture the enemy's flag?"] = "Auf welchem Schlachtfeld erobert Ihr die Flagge des Gegners?",
	["In which battleground do you hold the Stables, the Farm and the Lumber Mill?"] = "Auf welchem Schlachtfeld haltet Ihr die Ställe, den Hof und das Sägewerk?",
	["In which dungeon or raid do you face %s?"] = "In welchem Dungeon oder Schlachtzug trefft Ihr auf %s?",
	["In which starting area does a new %s wake up?"] = "In welchem Startgebiet erwacht ein neuer %s?",
	["In which zone does a new %s begin?"] = "In welchem Gebiet beginnt ein neuer %s?",
	["In which zone is %s?"] = "In welchem Gebiet liegt %s?",
	["In which zone is Dalaran sealed under a magic dome?"] = "In welchem Gebiet ist Dalaran unter einer magischen Kuppel versiegelt?",
	["In which zone is the entrance to %s?"] = "In welchem Gebiet liegt der Eingang zu %s?",
	["Include an EldoUI note"] = "Eine EldoUI-Notiz anhängen",
	["Include guild chat"] = "Gildenchat einbeziehen",
	["Include macros"] = "Makros einbeziehen",
	["Include offline crafters"] = "Offline-Handwerker einbeziehen",
	["Include pets"] = "Begleiter einbeziehen",
	["Include this character"] = "Diesen Charakter einbeziehen",
