	["Items new in your bags"] = "Neue Gegenstände in Euren Taschen",
	["Items on this list never get an action. Modifier + right-click an item with a glow to add it, or type it here."] = "Gegenstände auf dieser Liste erhalten nie eine Aktion. Zusatztaste + Rechtsklick auf einen leuchtenden Gegenstand fügt ihn hinzu, oder gebt ihn hier ein.",
	["Items per hour"] = "Gegenstände pro Stunde",
	["Items that always or never show."] = "Gegenstände, die immer oder nie erscheinen.",
